// Generated by Claude Code
package ui;

import javafx.scene.Node;
import javafx.scene.control.Button;
import javafx.scene.control.Hyperlink;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.Region;
import javafx.scene.shape.Rectangle;

/**
 * One of the two import panels. Before a folder is imported it shows the folder path and the file tree; once an
 * import succeeds it shrinks to a one-line summary, so the results table gets the room. The marker can still open
 * the files from the summary.
 */
final class ImportPanel {

    private static final String CHANGE_TEXT = "Change folder";
    private static final String SHOW_FILES = "Show files";
    private static final String HIDE_FILES = "Hide files";
    private static final String STILL_USING = "Still using the earlier folder: ";

    private final Button importButton;
    private final TextField folderField;
    private final Node browser;
    private final Node summary;
    private final Label summaryText;
    private final Hyperlink filesToggle;
    private final Label error;
    private boolean filesShown;

    ImportPanel(Button importButton, TextField folderField, Node browser, Node summary,
            Label summaryText, Hyperlink filesToggle, Label error) {
        this.importButton = importButton;
        this.folderField = folderField;
        this.browser = browser;
        this.summary = summary;
        this.summaryText = summaryText;
        this.filesToggle = filesToggle;
        this.error = error;
        filesToggle.setOnAction(event -> showFiles(!filesShown));
        // The file area never paints outside its own box, however short the window is.
        if (browser instanceof Region area) {
            Rectangle clip = new Rectangle();
            clip.widthProperty().bind(area.widthProperty());
            clip.heightProperty().bind(area.heightProperty());
            area.setClip(clip);
        }
    }

    /** Says why the chosen folder was not accepted; whatever was imported before stays as it is. */
    void reject(String message) {
        error.setText(message);
        Nodes.show(error, true);
        // The tick line describes the folder still in use, not the one just rejected.
        if (summary.isVisible() && !summaryText.getText().startsWith(STILL_USING)) {
            summaryText.setText(STILL_USING + summaryText.getText());
        }
    }

    /** Shows an accepted folder's path. */
    void accept(String folder) {
        folderField.setText(folder);
        Nodes.show(error, false);
    }

    /** Shrinks the panel to one line, such as "5 of 5 tester files valid". */
    void collapse(String text) {
        summaryText.setText(text);
        importButton.setText(CHANGE_TEXT);
        Nodes.show(summary, true);
        showFiles(false);
    }

    private void showFiles(boolean shown) {
        filesShown = shown;
        filesToggle.setText(shown ? HIDE_FILES : SHOW_FILES);
        Nodes.show(folderField, shown);
        Nodes.show(browser, shown);
    }

}
